// ============================================================
// DAILY TASK SELECTION
// ============================================================

export function getDailyTasks(resetCount: number = 0): TaskItem[] {
  const dateStr = new Date().toDateString()
  const tasks: TaskItem[] = []

  CATEGORIES.forEach(category => {
    const pool = ALL_TASKS[category]
    if (!pool) return

    const seed = dateStr + category + resetCount
    const seedNum = seed.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0)

    const shuffled = [...pool]
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.abs(Math.sin(seedNum + i) * 10000) % (i + 1) | 0
      ;[shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]]
    }

    const easy = shuffled.filter(t => t.difficulty === 'easy')
    const hard = shuffled.filter(t => t.difficulty === 'hard')
    const legendary = shuffled.filter(t => t.difficulty === 'legendary')

    const selected: RawTask[] = [
      easy[0], easy[1], hard[0], hard[1], legendary[0],
    ].filter(Boolean)

    while (selected.length < 5 && shuffled.length > selected.length) {
      const next = shuffled.find(t => !selected.includes(t))
      if (next) selected.push(next)
      else break
    }

    selected.forEach((task) => {
      const taskHash = task.label.substring(0, 8).replace(/\s/g, '_').toLowerCase()

      tasks.push({
        id: `${category}-${taskHash}`,
        category,
        label: task.label,
        penalty: task.penalty,
        xp: task.xp,
        difficulty: task.difficulty,
      })
    })
  })

  return tasks
}

export type Quest = {
  id: string
  label: string
  category: string
  xp: number
  startDate: string
  lastCheckin: string
  daysCompleted: number
  totalDays: number
  completed: boolean
}